hl.config({ input = { kb_layout = "us,ru,ua", kb_options = "grp:alt_shift_toggle", accel_profile = "flat" } })
-- Generated by nwg-displays on 2026-09-30 at 19:02:23. Do not edit manually.

hl.monitor({
    output = "eDP-1",
    mode = "1920x1080@60.02",
    position = "0x0",
    scale = 1.0,
    vrr = 0
})

hl.bind("SUPER + ALT + G", hl.dsp.exec_cmd("~/.local/bin/orrery-gamemode"))

-- Start user applications once when entering Hyprland.
-- uwsm app puts each one in its own scope: when memory runs out, systemd-oomd
-- kills that app instead of the compositor's cgroup (and with it the session).
hl.on("hyprland.start", function()
    hl.exec_cmd("uwsm app -- discord --start-minimized")
    -- Steam starts later and hidden so it doesn't fight Discord/Telegram for the 4 threads at login.
    -- It waits for the SCP:SL identity profile (source-active.json) first, so the
    -- autostart helper never finds Steam open and refuses to apply.
    hl.exec_cmd("sh -c 'sleep 20; exec /home/noras/scpsl-hwid/steam-after-profile.sh'")
    hl.exec_cmd("uwsm app -- Telegram")
    hl.exec_cmd("hyprctl switchxkblayout all 1")
end)

-- Satty (screenshot editor): a centred floating window, not a tile
hl.window_rule({ name = "satty-float", match = { class = "^(com.gabm.satty)$" }, float = true, center = true, size = "monitor_w*0.7 monitor_h*0.75" })

-- Dolphin (file manager): a centred floating window
hl.window_rule({ name = "dolphin-float", match = { class = "^(org.kde.dolphin)$" }, float = true, center = true, size = "monitor_w*0.6 monitor_h*0.7" })

-- Launcher opens without the compositor fade; its card already animates itself
hl.layer_rule({ match = { namespace = "^orrery-launcher$" }, no_anim = true })

-- Thunar (file manager): a centred floating window, like Dolphin above
hl.window_rule({ name = "thunar-float", match = { class = "^([Tt]hunar)$" }, float = true, center = true, size = "monitor_w*0.6 monitor_h*0.7" })
